contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry containing the whole test logic
    function run(address asset, uint256 depositAmount) public payable {
        require(address(c) != address(0)); // trivial sanity to avoid nonsense

        // Ensure this contract is funded enough for any ERC20.transferFrom expectations in some implementations
        // (we don't transfer Ether to c in this test). No Ether interactions with c are needed.

        // Read before-state: total deposits and c's balance of the asset (via getAssetDistributionData -> total)
        uint256 beforeTotal = c.getTotalAssetDeposits(asset);
        uint256 beforeBalanceOfC;
        // Try to read balanceOf via getAssetDistributionData which will revert if asset not supported.
        bool supportedBefore;
        uint256 assetLyingInDepositPool;
        uint256 assetLyingInNDCs;
        uint256 assetStakedInEigenLayer;
        supportedBefore = true;
        try c.getAssetDistributionData(asset) returns (uint256 a, uint256 b, uint256 d) {
            assetLyingInDepositPool = a;
            assetLyingInNDCs = b;
            assetStakedInEigenLayer = d;
            beforeBalanceOfC = a;
        } catch {
            // asset not supported -> we consider supportedBefore = false
            supportedBefore = false;
            beforeBalanceOfC = 0;
        }

        // Attempt depositAsset and capture whether it reverted
        bool reverted;
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state: total deposits and c balance (if supported)
        uint256 afterTotal = c.getTotalAssetDeposits(asset);
        bool supportedAfter = true;
        uint256 afterBalanceOfC;
        try c.getAssetDistributionData(asset) returns (uint256 a2, uint256 b2, uint256 d2) {
            afterBalanceOfC = a2;
        } catch {
            supportedAfter = false;
            afterBalanceOfC = 0;
        }

        // General rule asserted:
        // If the deposit call did NOT revert and the asset is supported (so transferFrom could have been attempted),
        // then the contract's total asset deposits must have increased by exactly depositAmount (reflecting that tokens were transferred into the pool),
        // OR if the asset is unsupported or other checks prevented change, the call must have reverted. In short: a non-reverting deposit must increase total deposits by depositAmount.
        assert(
            // If deposit did not revert and asset remains supported -> afterTotal == beforeTotal + depositAmount
            ( !reverted && supportedAfter && supportedBefore && afterTotal == beforeTotal + depositAmount )
            // Otherwise, if it did revert, afterTotal must equal beforeTotal (no silent state change on revert)
            || ( reverted && afterTotal == beforeTotal )
        );
    }

    // receive to accept Ether if needed by ERC20 tokens in some setups
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry containing the whole test logic
    function run(address asset, uint256 depositAmount) public payable {
        // keep domain small and avoid underflows in assertions
        require(address(c) != address(0));
        require(depositAmount > 0 && depositAmount <= type(uint256).max / 2);

        // We only reason about supported assets. If asset not supported, test does nothing meaningful.
        bool supported;
        uint256 beforeLimit;
        try c.getAssetCurrentLimit(asset) returns (uint256 lim) {
            supported = true;
            beforeLimit = lim;
        } catch {
            // asset not supported -> we stop by asserting trivially that call reverts (so we assert true)
            // but the final assert must be non-trivial; instead we require supported to be true so execution won't continue otherwise
            supported = false;
        }
        require(supported);

        // Attempt depositAsset and capture whether it reverted
        bool reverted;
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state limit (if supported, call should still succeed)
        uint256 afterLimit = c.getAssetCurrentLimit(asset);

        // General invariant: if deposit succeeded, the available limit cannot decrease by more than depositAmount.
        // i.e., beforeLimit >= afterLimit and (beforeLimit - afterLimit) <= depositAmount
        // To avoid underflow in the assert, we express as: afterLimit <= beforeLimit && afterLimit + depositAmount >= beforeLimit
        assert(reverted || (afterLimit <= beforeLimit && afterLimit + depositAmount >= beforeLimit));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry containing the whole test logic
    function run(uint256 ndcIndex, address asset, uint256 amount) public payable {
        // basic preconditions to keep values reasonable and avoid underflows in assertions
        require(address(c) != address(0));
        require(amount <= type(uint256).max / 4);

        // Ensure asset is supported by observing that getAssetCurrentLimit does not revert
        uint256 dummy;
        try c.getAssetCurrentLimit(asset) returns (uint256 v) {
            dummy = v;
        } catch {
            // if asset not supported, stop early by requiring support
            revert("asset not supported");
        }

        // Read total deposits before
        uint256 beforeTotal = c.getTotalAssetDeposits(asset);

        // Attempt the transfer; capture whether it reverted
        bool reverted;
        try c.transferAssetToNodeDelegator(ndcIndex, asset, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read total deposits after
        uint256 afterTotal = c.getTotalAssetDeposits(asset);

        // Assert the general rule: if transfer reverted then total must be unchanged; if it succeeded then total is <= beforeTotal (since tokens may have moved out of c)
        // Express without underflow: reverted ==> afterTotal == beforeTotal ; !reverted ==> afterTotal <= beforeTotal
        assert((reverted && afterTotal == beforeTotal) || (!reverted && afterTotal <= beforeTotal));
    }

    receive() external payable {}
}

